def parse_error_line(line):
    if ': ' not in line:
        return (line, '')
    error_type, message = line.split(': ', 1)
    return (error_type, message)

def deepest_line(traceback_text):
    frames = [l for l in traceback_text.split('\n') if l.startswith('  File ')]
    last = frames[-1]
    return int(last.split('line ')[1].split(',')[0])

