def item_at(items, index, default=None):
    if -len(items) <= index < len(items):
        return items[index]
    return default

def order_total(order, prices):
    total = 0
    missing = []
    for item, qty in order.items():
        if item in prices:
            total += prices[item] * qty
        else:
            missing.append(item)
    return total, missing

