solution.code:
def percent(part, whole):
    if whole == 0:
        return 0.0
    return round(part / whole * 100, 1)

print(percent(1, 3), percent(5, 0))

def to_number(text):
    text = text.strip()
    if text.isdigit():
        return int(text)
    parts = text.split('.')
    if len(parts) == 2 and parts[0].isdigit() and parts[1].isdigit():
        return float(text)
    return None

